script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.state.projectTemplateDetails.isTemplate) {
    return 'TEMPLATE';
  }
	return 'PROJECT';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const {
        projectPermissions: pp,
        projectTemplateDetails: pt
    } = api.state;
    return !(pt.isTemplate && pp.promin_project.fields.is_template.canWrite);
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'projectDetails',
		value: {
			...api.state.projectDetails,
			description: event.payload.fieldValue,
		}
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	if (!api.state.projectTemplateDetails.isTemplate) {
    if (api.state.isEditing) {
      return false;
    }
    return true;
  }
  return true;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	if(api.state.isEditing){
    return api.state.projectDetails.status;
  }else{
    return 'DRAFT';
  }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const {
        projectPermissions,
        resetPrimaryEntity,
    } = api.state;
    let hasAccess = true;
    if (api.context.props.projectId !== '-1') {
        hasAccess = projectPermissions.promin_project_entity.canCreate;
        if (hasAccess && resetPrimaryEntity) {
            return false;
        }
    }

    return (api.state.isEditing || !hasAccess);
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.context.props.projectId != -1) {
        return api.state.sourceTypeInput.find((type) => type.id == api.state.projectDetails?.sourceType)?.label || helpers.translateSync('Table');
    } else {
        if (api.state.sourceTypeName == 'Table') {
            return helpers.translateSync('Table');
        }
        return api.state.sourceTypeInput.find((type) => type.id == api.state.sourceType)?.label;
    }
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "restricted",
		value: event.payload.value
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const autoRetire={...api.state.autoRetire,value:event.payload.value};
	return {
		propName: "autoRetire",
		value: autoRetire
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.autoRetire.value;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.projectTemplateDetails.isTemplate;
}

